POP_ingress_settings:
# POP-only standard header processing; existing rules retained.
mail_pop_ingress_v1 {
  priority = 2;
  request_header { "MTA-Name" = "^mail_pop_ingress_v1$"; }
  apply {
    plugins { milter_headers { routines = ["spam-header", "x-spam-status"]; } }
    symbols_disabled = ["DKIM_SIGNED", "ARC_SIGNED"];
  }
}

sieve_configuration:
sieve_script personal {
 driver = file
 path = ~/sieve
 active_path = ~/.dovecot.sieve
}
sieve_script mail_feature_forward_v1 {
  type = before
  precedence = infinite
  path = /var/lib/mail-feature-public-v1/sieve/current/%{user}.sieve
}
